// HasAgents applies the HasEdge predicate on the "agents" edge.
func HasAgents() predicate.UserDeletion {
	return predicate.UserDeletion(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, AgentsTable, AgentsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAgentsWith applies the HasEdge predicate on the "agents" edge with a given conditions (other predicates).
func HasAgentsWith(preds ...predicate.UserDeletionAgent) predicate.UserDeletion {
	return predicate.UserDeletion(func(s *sql.Selector) {
		step := newAgentsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UserDeletion) predicate.UserDeletion {
	return predicate.UserDeletion(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UserDeletion) predicate.UserDeletion {
	return predicate.UserDeletion(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UserDeletion) predicate.UserDeletion {
	return predicate.UserDeletion(sql.NotPredicates(p))
}
